import { Stream } from '../../../exported-utils/models/stream';
export class SortController {
    constructor() {
        //Only neon code should directly access this property
        this.changeStream = new Stream();
    }
    /**
     * Gets the sort direction of the current column.
     * @returns The direction of the current column. Ascending, descending, or undefined.
     */
    getSortDirection() {
        return this.sortDirection;
    }
    /**
     * Sts the direction of the current column.
     * @param value The direction to be set. Ascending, descending, or undefined.
     */
    setSortDirection(value) {
        if (value !== this.sortDirection) {
            this.sortDirection = value;
            this.changeStream.fire();
        }
    }
    /**
     * Sets the column of the table and which direction it should be sorted.
     * @param sortControl The value matches up with the id or the name passed into the neon-table-header.
     * @param sortDirection The direction the table should be sorted. Ascending or descending.
     */
    setSortAndDirection(sortControl, sortDirection) {
        if (sortControl !== this.currentSortControl || sortDirection !== this.sortDirection) {
            this.currentSortControl = sortControl;
            this.sortDirection = sortDirection;
            this.changeStream.fire();
        }
    }
    /**
     * Gets the column of the table that is sorted.
     * @returns The value that matches up with the id or the name passed into the neon-table-header.
     */
    getCurrentSort() {
        return this.currentSortControl;
    }
    /**
     * Gets the change stream for the SortController. When the private values inside the SortController are changed
     * the stream is fired.
     * @returns A read only Stream object that can be subscribed to.
     */
    getChangeStream() {
        return this.changeStream.getReadOnlyStream();
    }
}
